-- OUTCOMES-6 (2026-10-13, pillar autonomy; doctrine section 22 prediction calibration): outcomes of 35 logged predictions whose window has elapsed, judged from live reads; misses are recorded as misses.
INSERT INTO decision_outcomes (decision_id, ts, observed_outcome, matched, evidence, actor)
SELECT d.id, strftime('%Y-%m-%dT%H:%M:%SZ', 'now'), o.column2, o.column3, 'OUTCOMES-6: ' || o.column4, 'session_01Kddqwk5gQT5qSSHVKjT2EA'
